#!/usr/bin/env Rscript
#
# T041: FDR Overlap Analysis
#
# Calculates the top-20 CRE overlap percentage between FDR thresholds (0.01, 0.05, 0.10)
# using GLS outputs (adjusted p-value, |beta1|).
#
# Input: results/CRE_ranked_<stress>.md (generated by T018)
# Output: results/fdr_overlap_stats.csv
#
# Dependencies:
#   - T016/T017: GLS fitting and FDR correction (produces ranked CRE files)
#
# FR-003: Validate peak calling FDR thresholds via overlap analysis
# SC-004: Verify stability of top-20 CREs across FDR cutoffs
#

library(dplyr)
library(readr)
library(stringr)

# Configuration
OUTPUT_FILE <- "results/fdr_overlap_stats.csv"
THRESHOLDS <- c(0.01, 0.05, 0.10)
TOP_N <- 20

# Helper to parse the Markdown table from T018 output
# T018 generates results/CRE_ranked_<stress>.md with a header and pipe-separated table
parse_cre_ranked_file <- function(file_path) {
  if (!file.exists(file_path)) {
    stop(paste("Input file not found:", file_path))
  }

  lines <- readLines(file_path, warn = FALSE)

  # Find the start of the table (line starting with |)
  table_start <- which(str_detect(lines, "^\\|"))
  if (length(table_start) == 0) {
    stop(paste("No table found in", file_path))
  }

  # Extract table lines (skip header separator if present)
  table_lines <- lines[table_start[length(table_start) - 1]:(length(lines))]

  # Parse pipe-separated values
  # Expected format: | chrom | start | end | tf | log2FC | beta1 | q_value | ... |
  parsed_data <- lapply(table_lines, function(line) {
    # Remove leading/trailing whitespace and pipes
    clean_line <- str_replace_all(line, "^\\s*\\||\\|\\s*$", "")
    str_split(clean_line, "\\s*\\|\\s*")[[1]]
  })

  if (length(parsed_data) < 2) {
    stop(paste("Insufficient table rows in", file_path))
  }

  # First row is header
  headers <- tolower(trimws(parsed_data[[1]]))
  data_rows <- parsed_data[-1]

  # Convert to data frame
  df <- as.data.frame(do.call(rbind, data_rows), stringsAsFactors = FALSE)
  colnames(df) <- headers

  # Convert numeric columns
  numeric_cols <- c("log2fc", "beta1", "q_value", "p_value")
  for (col in numeric_cols) {
    if (col %in% colnames(df)) {
      df[[col]] <- suppressWarnings(as.numeric(df[[col]]))
    }
  }

  return(df)
}

# Identify stress conditions from available ranked files
# T018 generates files named results/CRE_ranked_<stress>.md
find_stress_files <- function() {
  if (!dir.exists("results")) {
    stop("results/ directory not found. Ensure T018 has been run.")
  }

  files <- list.files("results", pattern = "^CRE_ranked_.*\\.md$", full.names = TRUE)
  if (length(files) == 0) {
    stop("No CRE_ranked_*.md files found. Ensure T018 has been run.")
  }

  # Extract stress name from filename
  stress_names <- str_replace_all(basename(files), "^CRE_ranked_|\\.md$", "")
  names(files) <- stress_names

  return(files)
}

# Calculate top-N overlap between two sets of CREs
# CREs are identified by their genomic coordinates (chrom:start-end)
calculate_overlap <- function(set1_coords, set2_coords) {
  if (length(set1_coords) == 0 || length(set2_coords) == 0) {
    return(0.0)
  }

  overlap_count <- sum(set1_coords %in% set2_coords)
  # Percentage relative to the smaller set (conservative estimate)
  # Alternatively, could use Jaccard or relative to set1
  # Using intersection / min(size1, size2) to show how much of the top list is preserved
  overlap_pct <- (overlap_count / min(length(set1_coords), length(set2_coords))) * 100
  return(overlap_pct)
}

# Main analysis function
run_overlap_analysis <- function() {
  cat("Starting FDR Overlap Analysis (T041)...\n")

  # Find all ranked CRE files
  stress_files <- find_stress_files()
  cat(paste("Found", length(stress_files), "stress conditions to analyze:\n"))
  cat(paste("  -", names(stress_files), "\n"))

  # Prepare results storage
  results_list <- list()

  for (stress_name in names(stress_files)) {
    cat(paste("\nProcessing stress condition:", stress_name, "\n"))
    file_path <- stress_files[[stress_name]]

    # Parse the ranked file
    cre_data <- parse_cre_ranked_file(file_path)

    # Validate required columns
    required_cols <- c("q_value", "beta1")
    missing_cols <- setdiff(required_cols, colnames(cre_data))
    if (length(missing_cols) > 0) {
      stop(paste("Missing required columns in", file_path, ":", paste(missing_cols, collapse = ", ")))
    }

    # Create unique coordinate identifier for each CRE
    # Assuming columns: chrom, start, end (common BED-like format)
    if (!all(c("chrom", "start", "end") %in% colnames(cre_data))) {
      # Fallback: try to find similar columns
      chrom_col <- grep("chrom", colnames(cre_data), ignore.case = TRUE, value = TRUE)[1]
      start_col <- grep("start", colnames(cre_data), ignore.case = TRUE, value = TRUE)[1]
      end_col <- grep("end", colnames(cre_data), ignore.case = TRUE, value = TRUE)[1]

      if (is.na(chrom_col) || is.na(start_col) || is.na(end_col)) {
        stop(paste("Cannot identify genomic coordinate columns in", file_path))
      }
      cre_data$coord_id <- paste(cre_data[[chrom_col]], cre_data[[start_col]], cre_data[[end_col]], sep = ":")
    } else {
      cre_data$coord_id <- paste(cre_data$chrom, cre_data$start, cre_data$end, sep = ":")
    }

    # Sort by q-value (ascending) then by |beta1| (descending) for tie-breaking
    cre_data <- cre_data %>%
      arrange(q_value, desc(abs(beta1)))

    # Extract top-20 CREs for each FDR threshold
    threshold_results <- list()

    for (thresh in THRESHOLDS) {
      significant_cre <- cre_data %>%
        filter(q_value <= thresh) %>%
        head(TOP_N)

      if (nrow(significant_cre) == 0) {
        threshold_results[[as.character(thresh)]] <- character(0)
      } else {
        threshold_results[[as.character(thresh)]] <- significant_cre$coord_id
      }
    }

    # Calculate pairwise overlaps between thresholds
    # We compare each pair of thresholds and record the overlap percentage
    overlap_pairs <- combn(names(threshold_results), 2, simplify = FALSE)

    pair_results <- lapply(overlap_pairs, function(pair) {
      t1 <- pair[1]
      t2 <- pair[2]
      set1 <- threshold_results[[t1]]
      set2 <- threshold_results[[t2]]

      overlap <- calculate_overlap(set1, set2)

      data.frame(
        stress = stress_name,
        threshold_1 = as.numeric(t1),
        threshold_2 = as.numeric(t2),
        n_top1 = length(set1),
        n_top2 = length(set2),
        overlap_count = sum(set1 %in% set2),
        overlap_pct = overlap,
        stringsAsFactors = FALSE
      )
    })

    if (length(pair_results) > 0) {
      stress_results <- do.call(rbind, pair_results)
      results_list[[stress_name]] <- stress_results
    }
  }

  # Combine all results
  if (length(results_list) == 0) {
    stop("No overlap results generated. Check input files.")
  }

  final_results <- do.call(rbind, results_list)

  # Ensure output directory exists
  dir.create("results", showWarnings = FALSE, recursive = TRUE)

  # Write output
  write_csv(final_results, OUTPUT_FILE)
  cat(paste("\nOverlap analysis complete. Results written to:", OUTPUT_FILE, "\n"))
  cat(paste("Total rows:", nrow(final_results), "\n"))

  # Print summary
  print(final_results)

  return(final_results)
}

# Run main function
if (!interactive()) {
  run_overlap_analysis()
}